async ({moduleSource, pendingNames}) => {
 const domain=await import('data:text/javascript;base64,'+btoa(unescape(encodeURIComponent(moduleSource))));
 const equal=(a,b)=>{if(JSON.stringify(a)!==JSON.stringify(b))throw Error('Values differ after native transaction')};
 const yes=(v,message)=>{if(!v)throw Error(message)};
 const setup=async()=>{
  const store=domain.createFinalDraftStore(),meta=domain.createFinalDraftMeta({draftKey:'native:'+crypto.randomUUID(),instrument:'composite-whole',attemptId:'native-attempt',attemptEpoch:2,definitionHash:'frozen-definition',contextSnapshotHash:'frozen-context',deliveryMode:'final_only',submissionId:'native-submission',instrumentMetadata:{provenance:'keep',trainingScaleTiming:{items:{old:1}}}});
  await store.ensure(meta);const old=[{draftKey:meta.draftKey,itemKey:'old-only',value:'preserve on failure',updatedAt:1},{draftKey:meta.draftKey,itemKey:'shared',value:'old',updatedAt:1}];for(const a of old)await store.putAnswer(a);
  const next=[{draftKey:meta.draftKey,itemKey:'new-only',value:'restored',updatedAt:2},{draftKey:meta.draftKey,itemKey:'shared',value:'new',updatedAt:2}],timing={trainingScaleTiming:{items:{restored:2}}};return{store,meta,old,next,timing};
 };
 const rejected=async p=>{let error;try{await p}catch(e){error=e}yes(error,'Native write must reject');return error};
 const cases=[
  async()=>{const x=await setup(),put=IDBObjectStore.prototype.put;let observed=false;try{IDBObjectStore.prototype.put=function(value,key){const r=put.call(this,value,key);if(this.name==='draftAnswers'&&value.itemKey==='new-only')r.addEventListener('success',()=>{observed=true;this.transaction.abort()});return r};await rejected(x.store.replaceAnswers(x.meta,x.next,x.timing));}finally{IDBObjectStore.prototype.put=put}yes(observed,'Must reach inserted native row before abort');equal(await x.store.listAnswers(x.meta.draftKey),x.old);equal((await x.store.get(x.meta.draftKey)).instrumentMetadata,x.meta.instrumentMetadata);await x.store.delete(x.meta.draftKey)},
  async()=>{const x=await setup(),put=IDBObjectStore.prototype.put;try{IDBObjectStore.prototype.put=function(value,key){if(this.name==='draftMeta')throw new DOMException('Injected metadata quota failure','QuotaExceededError');return put.call(this,value,key)};await rejected(x.store.replaceAnswers(x.meta,x.next,x.timing));}finally{IDBObjectStore.prototype.put=put}equal(await x.store.listAnswers(x.meta.draftKey),x.old);equal((await x.store.get(x.meta.draftKey)).instrumentMetadata,x.meta.instrumentMetadata);await x.store.delete(x.meta.draftKey)},
  async()=>{const x=await setup(),transaction=IDBDatabase.prototype.transaction;let committed=false;try{IDBDatabase.prototype.transaction=function(...args){const t=transaction.apply(this,args);if(args[1]==='readwrite')t.addEventListener('complete',()=>{committed=true});return t};await x.store.replaceAnswers(x.meta,x.next,x.timing);yes(committed,'Promise must resolve after native transaction complete');}finally{IDBDatabase.prototype.transaction=transaction}equal(await x.store.listAnswers(x.meta.draftKey),x.next);await x.store.delete(x.meta.draftKey)},
  async()=>{const x=await setup(),put=IDBObjectStore.prototype.put;try{IDBObjectStore.prototype.put=function(value,key){if(this.name==='draftMeta')throw new DOMException('Injected answer/timing quota failure','QuotaExceededError');return put.call(this,value,key)};await rejected(x.store.putAnswer({...x.next[1]},x.timing));}finally{IDBObjectStore.prototype.put=put}equal(await x.store.listAnswers(x.meta.draftKey),x.old);equal((await x.store.get(x.meta.draftKey)).instrumentMetadata,x.meta.instrumentMetadata);await x.store.delete(x.meta.draftKey)},
  async()=>{const x=await setup();const write=x.store.putAnswer(x.next[1],x.timing),seal=x.store.sealForSubmission(x.meta.draftKey,s=>({answers:s.answers,timing:s.meta.instrumentMetadata}));await write;const result=await seal;equal(result.payload.answers.find(a=>a.itemKey==='shared'),x.next[1]);equal(result.payload.timing,{provenance:'keep',...x.timing});await rejected(x.store.putAnswer(x.old[1],{timing:'late'}));equal((await x.store.sealForSubmission(x.meta.draftKey,()=>{throw Error('Must not rebuild FINAL')})).payload,result.payload);await x.store.delete(x.meta.draftKey)}
 ];
 const names=[...pendingNames,'Native timed answer rolls back both values on metadata quota failure','Native following seal sees matching answer and timing and replays immutable FINAL'];const results=[];
 for(let i=0;i<cases.length;i++){const start=performance.now();await cases[i]();results.push({name:names[i],status:'passed',durationMs:performance.now()-start})}
 return{nativeIndexedDb:typeof IDBObjectStore==='function',results};
}
